#include <memory>
#include <utility>

// Payoff and Call are loaded. Write Forward and Scaled, both derived from Payoff.

prelude:
#include <algorithm>
#include <memory>
#include <vector>

class Payoff {
public:
    virtual ~Payoff() = default;
    virtual double operator()(double spot) const = 0;
};

class Call : public Payoff {
public:
    explicit Call(double k) : k_(k) {}
    double operator()(double spot) const override { return std::max(spot - k_, 0.0); }
private:
    double k_;
};

solution:
#include <memory>
#include <utility>

class Forward : public Payoff {
public:
    explicit Forward(double k) : k_(k) {}
    double operator()(double spot) const override { return spot - k_; }
private:
    double k_;
};

class Scaled : public Payoff {
public:
    Scaled(double qty, std::unique_ptr<Payoff> inner) : qty_(qty), inner_(std::move(inner)) {}
    double operator()(double spot) const override { return qty_ * (*inner_)(spot); }
private:
    double qty_;
    std::unique_ptr<Payoff> inner_;
};

